def trace(requirements, results, released):
    out = {}
    for req in requirements:
        rs = [r for r in results if r['req'] == req]
        current = [r for r in rs if r['model'] == released]
        if not rs:
            out[req] = 'NO EVIDENCE'
        elif not current:
            out[req] = 'WRONG VERSION'
        elif any(r['passed'] for r in current):
            out[req] = 'PASS'
        else:
            out[req] = 'FAIL'
    return out

