import hashlib

def _h(text):
    return hashlib.sha256(text.encode()).hexdigest()

def make_manifest(artefacts):
    return {name: _h(content) for name, content in artefacts.items()}

def verify(artefacts, manifest):
    changed = sorted(n for n in artefacts if n in manifest and _h(artefacts[n]) != manifest[n])
    missing = sorted(n for n in manifest if n not in artefacts)
    extra = sorted(n for n in artefacts if n not in manifest)
    return {'changed': changed, 'missing': missing, 'extra': extra}
